#include <LiquidCrystal.h>

// LCD Pinleri: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int trigPin = 9;
const int echoPin = 8;
const int yesilLed = 7;
const int kirmiziLed = 6;

long sure;
int mesafe;

void setup() {
  lcd.begin(16, 2);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(yesilLed, OUTPUT);
  pinMode(kirmiziLed, OUTPUT);

  lcd.print("Park Sensoru");
  lcd.setCursor(0, 1);
  lcd.print("Baslatiliyor...");
  delay(1500);
  lcd.clear();
}

void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  sure = pulseIn(echoPin, HIGH);
  mesafe = sure * 0.034 / 2;

  lcd.setCursor(0, 0);
  lcd.print("Mesafe: ");
  lcd.print(mesafe);
  lcd.print(" cm   ");

  lcd.setCursor(0, 1);
  if (mesafe < 10) {
    lcd.print("DUR! Cok Yakin  ");
    digitalWrite(kirmiziLed, HIGH);
    digitalWrite(yesilLed, LOW);
  } else if (mesafe >= 10 && mesafe <= 30) {
    lcd.print("Dikkat! Yakin   ");
    digitalWrite(kirmiziLed, HIGH);
    digitalWrite(yesilLed, HIGH);
  } else {
    lcd.print("Alan Guvenli    ");
    digitalWrite(kirmiziLed, LOW);
    digitalWrite(yesilLed, HIGH);
  }

  delay(200);
}
